contract ERC20Token is ERC20 {
    function ERC20Token(
        uint256 initialSupply,
        string tokenName,
        uint8 decimalUnits,
        string tokenSymbol
        ) public {
        totalSupply = initialSupply * 10 ** decimalUnits;
        name = tokenName;
        symbol = tokenSymbol;
        decimals = decimalUnits;
    }
}
